package com.sunwayworld.framework;
import com.sunwayworld.owned.internal.web.OwnedIdentityConfiguration;import com.sunwayworld.owned.internal.web.OwnedVocQueryController;import java.lang.reflect.Method;import java.util.Arrays;import java.util.HashSet;import java.util.Set;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PostMapping;
public final class OwnedVocQueryControllerContractTest{public static void main(String[] args){Set<String>paths=new HashSet<String>();for(Method m:OwnedVocQueryController.class.getDeclaredMethods()){PostMapping p=m.getAnnotation(PostMapping.class);if(p!=null)paths.addAll(Arrays.asList(p.path()));GetMapping g=m.getAnnotation(GetMapping.class);if(g!=null)paths.addAll(Arrays.asList(g.path()));}for(String x:new String[]{"/secure/emc/module/bp/voc/queries","/secure/emc/module/bp/voc/queries/raw","/secure/emc/module/bp/voc/queries/searchable","/secure/emc/module/bp/voc/info/status","/secure/emc/module/bp/voc/{id}"})if(!paths.contains(x))throw new AssertionError("missing VOC route "+x);boolean registered=false;for(Method m:OwnedIdentityConfiguration.class.getDeclaredMethods())if(m.getReturnType()==OwnedVocQueryController.class)registered=true;if(!registered)throw new AssertionError("VOC controller is not registered");System.out.println("owned VOC query contract checks passed");}}
